mapper.select:
select count(*)
from   tb_client_mst
where  business_No = #{businessNo}

SELECT a.business_no AS businessNo ,m.business_manager_name AS businessManagerName ,a.client_name AS clientName ,a.president AS president ,(SELECT ad.location FROM tb_client_address ad WHERE ad.client_id = a.client_id AND ad.order_dist = 1 ) AS location ,( SELECT ap.approval_option FROM tb_client_approval ap WHERE ap.client_id = a.client_id AND ap.order_dist = 1) AS approvalOption ,a.client_reg_date AS clientRegDate ,d1.sales_amt AS oneYearAgo ,d2.sales_amt AS twoYearAgo ,d3.sales_amt AS threeYearAgo ,( SELECT min(cm.contract_date) FROM tb_contract_mst cm WHERE cm.client_id = a.client_id ) AS firstDealDate ,( SELECT MAX(cm.contract_date) FROM tb_contract_mst cm WHERE cm.client_id = a.client_id ) AS lastDealDate ,a.client_type AS clientType ,a.client_type_name AS clientTypeName ,a.trade_type AS tradeType ,a.respon_sales_biz AS responSalesBiz ,a.establish_date AS establishDate ,a.business_type AS businessType ,a.business_item AS businessItem ,a.tel_no AS telNo ,a.fax_no AS faxNo ,a.homepage AS homepage ,a.email AS email ,a.group_cd AS groupCd ,a.group_name AS groupName ,a.groups_cd AS groupsCd ,a.groups_name AS groupsName ,a.payment_cd AS paymentCd ,a.payment_name AS paymentName ,isnull(a.manager_rank, a.manager_rank2) AS managerRank ,a.client_id AS clientId FROM tb_client_mst a LEFT JOIN tb_client_deal d1 ON d1.client_id = a.client_id AND d1.year = CONVERT(VARCHAR(4), YEAR(GETDATE()) - 1) LEFT JOIN tb_client_deal d2 ON d2.client_id = a.client_id AND d2.year = CONVERT(VARCHAR(4), YEAR(GETDATE()) - 2) LEFT JOIN tb_client_deal d3 ON d3.client_id = a.client_id AND d3.year = CONVERT(VARCHAR(4), YEAR(GETDATE()) - 3) LEFT JOIN tb_client_manager m ON m.client_id = a.client_id AND m.order_dist = 1 where 1=1
AND a.client_reg_date BETWEEN #{strDate} AND #{endDate}
AND a.manager_rank2 BETWEEN #{managerRank2From} AND #{managerRank2To}
AND a.client_name LIKE CONCAT('%', #{clientName}, '%')
AND a.business_no LIKE CONCAT('%', #{businessNo}, '%')
AND m.business_manager_name = #{businessManagerName}
AND a.client_type = #{clientType}
AND a.trade_type = #{tradeType}
AND a.use_yn = #{useYn}
ORDER BY a.client_reg_date desc, a.client_id desc

