mapper.update:
UPDATE tb_client_mst
SET    business_no       = #{businessNo}
      ,client_name       = #{clientName}
      ,client_type       = #{clientType}
      ,client_type_name  = #{clientTypeName}
      ,trade_type        = #{tradeType}
      ,respon_sales_biz  = #{responSalesBiz}
      ,establish_date    = #{establishDate, jdbcType=DATE}
      ,president         = #{president}
      ,business_type     = #{businessType}
      ,business_item     = #{businessItem}
      ,tel_no            = #{telNo}
      ,fax_no            = #{faxNo}
      ,homepage          = #{homepage}
      ,email             = #{email}
      ,group_cd          = #{groupCd}
      ,group_name        = #{groupName}
      ,groups_cd         = #{groupsCd}
      ,groups_name       = #{groupsName}
      ,payment_cd        = #{paymentCd}
      ,payment_name      = #{paymentName}
      ,manager_rank      = #{managerRank}
      ,manager_rank2     = #{managerRank2}
      ,use_yn            = #{useYn}
      ,upd_id            = #{userId}
      ,upd_dt            = GETDATE()
WHERE client_id = #{clientId};

UPDATE tb_client_approval
SET    approval_option = #{approvalOption}
      ,first_amt       = #{firstAmt}
      ,middle_amt      = #{middleAmt}
      ,last_amt        = #{lastAmt}
      ,credit          = #{credit}
      ,credit_period   = #{creditPeriod}
      ,payment_method  = #{paymentMethod}
      ,order_dist      = #{orderDist}
      ,upd_id          = #{userId}
      ,upd_dt          = GETDATE()
WHERE client_approval_id = #{clientApprovalId}
AND   client_id = #{clientId}

