      ,manager_name   = #{managerName}
      ,last_deal_date = #{lastDealDate}
      ,order_dist     = #{orderDist}
      ,upd_id         = #{userId}
      ,upd_dt         = GETDATE()
WHERE client_deal_id = #{clientDealId}
  AND client_id = #{clientId}

